(** * note_commit_r fixed-base window-sign (positive QR) computational certificate

    For every window [w] (0..84) and digit [i] (0..7) of the note_commit_r
    fixed-base table, the true Weierstrass multiple's y-coordinate is the
    quadratic-residue-admitting root selected by the z-table:

      is_square
        (UnOp.from
          (EccSpec.fw_z <window w> +F
            Point.y (PallasModel.repr <multiple w i>))) = true

    where [<window w> = List.nth w (OrchardCircuitSpec.note_commit_r
    OrchardActionFixedBase.orchard_internal_params)
    OrchardActionFixedBase.fixed_window_default] and
    the multiple [<multiple w i> = List.nth i (List.nth w
    NoteCommitRFullTable.full_table []) Pallas.identity] is read from the shared
    table leaf ([circuit_proof/note_commit_r/table.v]) — the
    octupling-chain-computed table of all 85*8 multiples of the note_commit_r
    generator.  The y-analogue of the x-coordinate certificate
    [NoteCommitRFixedWindowCert.x_check_true]; the per-entry extraction
    [y_check_entry] is consumed by the ladder file, whose bridge lemmas
    rewrite the [full_table] entry to the Weierstrass multiple.

    The checker scaffolding is the shared [FixedBaseSignCert] section
    ([circuit_proof/cert_defs.v]); this file keeps only its
    [root_table] witness data and the single [vm_compute] certificate
    [root_check_true] — one field multiplication per entry over the table
    leaf's [full_table_reduced] literal, stated as the raw [forallb] term so
    the extraction type-checks syntactically.  If any entry's y were not the
    QR-admitting root (a genuine underconstraint: two admissible window-point
    signs), no root witness could exist and the certificate would fail rather
    than lie.  The QR chain is held [Strategy opaque] so the kernel's
    conversion oracle never expands [is_square] to a [modpow] over the
    concrete Pallas [(p-1)/2] exponent.  This file reads the shared table
    READ-ONLY — the octupling chain is paid once, there, by
    [full_table_reduced_eq], never here. *)

Require Import Garden.Field.Field.
Require Import Garden.Field.Sqrt.
Require Import Garden.EllipticCurve.Weierstrass.
Require Import Garden.EllipticCurve.Pallas.
Require Import Garden.Halo2.lemmas.
Require Import Garden.Halo2.halo2_gadgets.ecc.chip.spec.
Require Import Garden.Halo2.PallasModel.
Require Import Garden.Orchard.protocol_spec.
Require Import Garden.Orchard.circuit_proof.internal_spec.
Require Import Garden.Orchard.circuit_proof.fixed_base.main.
Require Import Garden.Orchard.circuit_proof.table_defs.
Require Import Garden.Orchard.circuit_proof.cert_defs.
Require Import Garden.Orchard.circuit_proof.note_commit_r.table.
Require Import Stdlib.ZArith.ZArith.
Require Import Stdlib.Lists.List.
Require Import Stdlib.Bool.Bool.
Import ListNotations.

#[local] Existing Instance Primes.PallasPIsPrime.

Global Open Scope Z_scope.

(* Keep the square-root / QR chain opaque to the kernel's conversion oracle so
   up-to-conversion matching in the derivations below never evaluates [modpow]
   over the concrete Pallas [(p-1)/2] exponent (which blows the term up). *)
Strategy opaque [is_square modpow modpow_pos field_sqrt].

(* Keep the table constants opaque to unification/conversion in this file
   ([Opaque] is file-local; [vm_compute] ignores it, and the literal is
   already a value). *)
Opaque NoteCommitRFullTable.full_table.
Opaque NoteCommitRFullTable.full_table_reduced.

